	OAuth2Authorization user2Authorization = this.authorizationService.findByToken(authorizationCode,
			AUTHORIZATION_CODE_TOKEN_TYPE);

	mvcResult = this.mvc
		.perform(post(DEFAULT_TOKEN_ENDPOINT_URI)
