public void slidingWindowAggregateOverlappingWindowsTest() {

    final KTable<Windowed<String>, String> customers = groupedStream.cogroup(MockAggregator.TOSTRING_ADDER)
            .windowedBy(SlidingWindows.withTimeDifferenceAndGrace(ofMillis(WINDOW_SIZE_MS), ofMillis(2000L))).aggregate(
                    MockInitializer.STRING_INIT, Materialized.with(Serdes.String(), Serdes.String()));
    customers.toStream().to(OUTPUT);

    try (final TopologyTestDriver driver = new TopologyTestDriver(builder.build(), props)) {
        final TestInputTopic<String, String> testInputTopic = driver.createInputTopic(
                TOPIC, new StringSerializer(), new StringSerializer());
        final TestOutputTopic<Windowed<String>, String> testOutputTopic = driver.createOutputTopic(
                OUTPUT, new TimeWindowedDeserializer<>(new StringDeserializer(), WINDOW_SIZE_MS), new StringDeserializer());

        testInputTopic.pipeInput("k1", "A", 500);
        testInputTopic.pipeInput("k2", "A", 500);
        testInputTopic.pipeInput("k1", "B", 750);
        testInputTopic.pipeInput("k2", "B", 750);
        testInputTopic.pipeInput("k2", "A", 1000L);
        testInputTopic.pipeInput("k1", "A", 1000L);

        // left window k1@500
        assertOutputKeyValueTimestamp(testOutputTopic, "k1", "0+A", 500);
        // left window k2@500
        assertOutputKeyValueTimestamp(testOutputTopic, "k2", "0+A", 500);
        // right window k1@500
        assertOutputKeyValueTimestamp(testOutputTopic, "k1", "0+B", 750);
        // left window k1@750
        assertOutputKeyValueTimestamp(testOutputTopic, "k1", "0+A+B", 750);
        // right window k2@500
        assertOutputKeyValueTimestamp(testOutputTopic, "k2", "0+B", 750);
        // left window k2@750
        assertOutputKeyValueTimestamp(testOutputTopic, "k2", "0+A+B", 750);
        // right window k2@500 update
        assertOutputKeyValueTimestamp(testOutputTopic, "k2", "0+B+A", 1000);
        // right window k2@750
        assertOutputKeyValueTimestamp(testOutputTopic, "k2", "0+A", 1000);
        // left window k2@1000
        assertOutputKeyValueTimestamp(testOutputTopic, "k2", "0+A+B+A", 1000);
        // right window k1@500 update
        assertOutputKeyValueTimestamp(testOutputTopic, "k1", "0+B+A", 1000);
        // right window k1@750
        assertOutputKeyValueTimestamp(testOutputTopic, "k1", "0+A", 1000);
        // left window k1@1000
        assertOutputKeyValueTimestamp(testOutputTopic, "k1", "0+A+B+A", 1000);
    }
}

public void connectionSettingsPropagated() throws Exception {
  final int originalLowWaterMark = 2097169;
  final int originalHighWaterMark = 2097211;

  Map<ChannelOption<?>, Object> childChannelOptions = new HashMap<>();
  childChannelOptions.put(ChannelOption.WRITE_BUFFER_WATER_MARK,
      new WriteBufferWaterMark(originalLowWaterMark, originalHighWaterMark));

  class TestChannelHandler extends ChannelHandlerAdapter {
    CountDownLatch countDownLatch = new CountDownLatch(1);
    int lowWaterMark;
    int highWaterMark;

    @Override public void handlerAdded(ChannelHandlerContext ctx) {
      Channel channel = ctx.channel();
      WriteBufferWaterMark writeBufferWaterMark = channel.config()
          .getOption(ChannelOption.WRITE_BUFFER_WATER_MARK);
      lowWaterMark = writeBufferWaterMark.low();
      highWaterMark = writeBufferWaterMark.high();

      countDownLatch.countDown();
    }
  }

  final TestChannelHandler channelHandler = new TestChannelHandler();

  class TestProtocolNegotiator implements ProtocolNegotiator {
    Attributes eagAttributes;

    @Override public ChannelHandler newHandler(GrpcHttp2ConnectionHandler handler) {
      eagAttributes = handler.getEagAttributes();
      return channelHandler;
    }

    @Override public void close() {}

    @Override public AsciiString scheme() {
      return Utils.HTTP;
    }
  }

  Attributes eagAttributes = Attributes.newBuilder()
      .set(Attributes.Key.create("foo"), "bar")
      .build();
  TestProtocolNegotiator protocolNegotiator = new TestProtocolNegotiator();
  InetSocketAddress addr = new InetSocketAddress(0);
  NettyServer ns =
      new NettyServer(
          Arrays.asList(addr),
          new ReflectiveChannelFactory<>(NioServerSocketChannel.class),
          new HashMap<ChannelOption<?>, Object>(),
          childChannelOptions,
          new FixedObjectPool<>(eventLoop),
          new FixedObjectPool<>(eventLoop),
          false,
          protocolNegotiator,
          Collections.<ServerStreamTracer.Factory>emptyList(),
          TransportTracer.getDefaultFactory(),
          1, // ignore
          false, // ignore
          1, // ignore
          1, // ignore
          1, // ignore
          1, // ignore
          1, // ignore
          1,
          1, // ignore
          1,
          1, // ignore
          true,
          0, // ignore
          0,
          0, // ignore
          eagAttributes,
          channelz);
  ns.start(new ServerListener() {
    @Override
    public ServerTransportListener transportCreated(ServerTransport transport) {
      return new NoopServerTransportListener();
    }

    @Override
    public void serverShutdown() {}
  });

  Socket socket = new Socket();
  socket.connect(ns.getListenSocketAddress(), /* timeout= */ 8000);
  channelHandler.countDownLatch.await();
  socket.close();

  assertThat(protocolNegotiator.eagAttributes).isSameInstanceAs(eagAttributes);
  assertThat(channelHandler.lowWaterMark).isEqualTo(originalLowWaterMark);
  assertThat(channelHandler.highWaterMark).isEqualTo(originalHighWaterMark);

  ns.shutdown();
}

