public void testPutLogLevel() throws Exception {
    final String logger1 = "org.apache.zookeeper";
    final String logger2 = "org.apache.cassandra";
    final String logger3 = "org.apache.kafka.clients";
    final String logger4 = "org.apache.kafka.connect";
    final String level1 = "ERROR";
    final String level3 = "WARN";
    final String level4 = "DEBUG";

    final Struct existingLogLevel = new Struct(KafkaConfigBackingStore.LOGGER_LEVEL_V0)
            .put("level", level1);

    // Pre-populate the config topic with a couple of logger level records; these should be ignored (i.e.,
    // not reported to the update listener)
    List<ConsumerRecord<String, byte[]>> existingRecords = Arrays.asList(
            new ConsumerRecord<>(TOPIC, 0, 0, 0L, TimestampType.CREATE_TIME, 0, 0, "logger-cluster-" + logger1,
                    CONFIGS_SERIALIZED.get(0), new RecordHeaders(), Optional.empty()
            ),
            new ConsumerRecord<>(TOPIC, 0, 1, 0L, TimestampType.CREATE_TIME, 0, 0, "logger-cluster-" + logger2,
                    CONFIGS_SERIALIZED.get(1), new RecordHeaders(), Optional.empty()
            )
    );
    LinkedHashMap<byte[], Struct> deserialized = new LinkedHashMap<>();
    deserialized.put(CONFIGS_SERIALIZED.get(0), existingLogLevel);
    // Make sure we gracefully handle tombstones
    deserialized.put(CONFIGS_SERIALIZED.get(1), null);
    logOffset = 2;

    expectStart(existingRecords, deserialized);
    when(configLog.partitionCount()).thenReturn(1);

    configStorage.setupAndCreateKafkaBasedLog(TOPIC, config);
    verifyConfigure();

    configStorage.start();
    verify(configLog).start();

    expectConvertWriteRead(
            "logger-cluster-" + logger3, KafkaConfigBackingStore.LOGGER_LEVEL_V0, CONFIGS_SERIALIZED.get(2),
            "level", level3);
    configStorage.putLoggerLevel(logger3, level3);

    expectConvertWriteRead(
            "logger-cluster-" + logger4, KafkaConfigBackingStore.LOGGER_LEVEL_V0, CONFIGS_SERIALIZED.get(3),
            "level", level4);
    configStorage.putLoggerLevel(logger4, level4);

    LinkedHashMap<String, byte[]> newRecords = new LinkedHashMap<>();
    newRecords.put("logger-cluster-" + logger3, CONFIGS_SERIALIZED.get(2));
    newRecords.put("logger-cluster-" + logger4, CONFIGS_SERIALIZED.get(3));
    doAnswer(expectReadToEnd(newRecords)).when(configLog).readToEnd();

    configStorage.refresh(0, TimeUnit.SECONDS);
    verify(configUpdateListener).onLoggingLevelUpdate(logger3, level3);
    verify(configUpdateListener).onLoggingLevelUpdate(logger4, level4);

    configStorage.stop();
    verify(configLog).stop();
}

private <T> FutureRecordMetadata expectAppendWithAbortForNewBatch(
    KafkaProducerTestContext<T> ctx,
    ProducerRecord<T, T> record,
    TopicPartition initialSelectedPartition,
    TopicPartition retrySelectedPartition,
    Cluster cluster
) throws InterruptedException {
    byte[] serializedKey = ctx.serializer.serialize(topic, record.key());
    byte[] serializedValue = ctx.serializer.serialize(topic, record.value());
    long timestamp = record.timestamp() == null ? ctx.time.milliseconds() : record.timestamp();

    ProduceRequestResult requestResult = new ProduceRequestResult(retrySelectedPartition);
    FutureRecordMetadata futureRecordMetadata = new FutureRecordMetadata(
        requestResult,
        0,
        timestamp,
        serializedKey.length,
        serializedValue.length,
        ctx.time
    );

    when(ctx.partitioner.partition(
        initialSelectedPartition.topic(),
        record.key(),
        serializedKey,
        record.value(),
        serializedValue,
        cluster
    )).thenReturn(initialSelectedPartition.partition())
      .thenReturn(retrySelectedPartition.partition());

    when(ctx.accumulator.append(
        eq(initialSelectedPartition.topic()),            // 0
        eq(initialSelectedPartition.partition()),        // 1
        eq(timestamp),                                   // 2
        eq(serializedKey),                               // 3
        eq(serializedValue),                             // 4
        eq(Record.EMPTY_HEADERS),                        // 5
        any(RecordAccumulator.AppendCallbacks.class),    // 6 <--
        anyLong(),
        eq(true), // abortOnNewBatch
        anyLong(),
        any()
    )).thenAnswer(invocation -> {
        RecordAccumulator.AppendCallbacks callbacks =
            (RecordAccumulator.AppendCallbacks) invocation.getArguments()[6];
        callbacks.setPartition(initialSelectedPartition.partition());
        return new RecordAccumulator.RecordAppendResult(
            null,
            false,
            false,
            true,
            0);
    });

    when(ctx.accumulator.append(
        eq(retrySelectedPartition.topic()),              // 0
        eq(retrySelectedPartition.partition()),          // 1
        eq(timestamp),                                   // 2
        eq(serializedKey),                               // 3
        eq(serializedValue),                             // 4
        eq(Record.EMPTY_HEADERS),                        // 5
        any(RecordAccumulator.AppendCallbacks.class),    // 6 <--
        anyLong(),
        eq(false), // abortOnNewBatch
        anyLong(),
        any()
    )).thenAnswer(invocation -> {
        RecordAccumulator.AppendCallbacks callbacks =
            (RecordAccumulator.AppendCallbacks) invocation.getArguments()[6];
        callbacks.setPartition(retrySelectedPartition.partition());
        return new RecordAccumulator.RecordAppendResult(
            futureRecordMetadata,
            false,
            true,
            false,
            0);
    });

    return futureRecordMetadata;
}

