    if (emitFinal) {
        supplier = RocksDbIndexedTimeOrderedWindowBytesStoreSupplier.create(
            WINDOW_STORE_NAME,
            Duration.ofDays(1),
            Duration.ofMillis(windowSize),
            false,
            false
        );
