            .containsEntry("foo.response.length#count{hostname.pattern=*,http.status=200,method=POST," +
                           serviceTag + '}', 1.0)
            .containsEntry("foo.total.duration#count{hostname.pattern=*,http.status=200,method=POST," +
                           serviceTag + '}', 1.0);
}

