public void testAttributePropInclusion() throws Exception
{
    // first, with desc
    String json = WRITER.withAttribute("desc", "nice")
            .writeValueAsString(new OptionalsBean());
    assertEquals(a2q("{'value':28,'desc':'nice'}"), json);

    // then with null (not defined)
