    ProduceRequest.Builder builder = ProduceRequest.forCurrentMagic(new ProduceRequestData()
            .setTopicData(new ProduceRequestData.TopicProduceDataCollection())
            .setAcks((short) 1)
            .setTimeoutMs(1000));
