public void testNonObfuscatedBuild() throws IOException {
  Path proguardConfigFile = Paths.get("the/configuration.txt");
  Path proguardMappingFile = Paths.get("the/mapping.txt");

  ProjectFilesystem projectFilesystem = new FakeProjectFilesystem();
  projectFilesystem.writeLinesToPath(ImmutableList.of("-dontobfuscate"), proguardConfigFile);

  SplitZipStep splitZipStep =
      new SplitZipStep(
          projectFilesystem,
          /* inputPathsToSplit */ ImmutableSet.of(),
          /* secondaryJarMetaPath */ Paths.get(""),
          /* primaryJarPath */ Paths.get(""),
          /* secondaryJarDir */ Paths.get(""),
          /* secondaryJarPattern */ "",
          /* additionalDexStoreJarMetaPath */ Paths.get(""),
          /* additionalDexStoreJarDir */ Paths.get(""),
          /* proguardFullConfigFile */ Optional.of(proguardConfigFile),
          /* proguardMappingFile */ Optional.of(proguardMappingFile),
          false,
          new DexSplitMode(
              /* shouldSplitDex */ true,
              ZipSplitter.DexSplitStrategy.MAXIMIZE_PRIMARY_DEX_SIZE,
              DexStore.JAR,
              /* linearAllocHardLimit */ 4 * 1024 * 1024,
              /* primaryDexPatterns */ ImmutableSet.of("primary"),
              /* primaryDexClassesFile */ Optional.empty(),
              /* primaryDexScenarioFile */ Optional.empty(),
              /* isPrimaryDexScenarioOverflowAllowed */ false,
              /* secondaryDexHeadClassesFile */ Optional.empty(),
              /* secondaryDexTailClassesFile */ Optional.empty(),
              /* allowRDotJavaInSecondaryDex */ false),
          Optional.empty(),
          Optional.empty(),
          Optional.empty(),
          Optional.empty(),
          /* additionalDexStoreToJarPathMap */ ImmutableMultimap.of(),
          /* pathToReportDir */
          ImmutableSortedMap.of(),
          null,
          Paths.get(""));

  ProguardTranslatorFactory translatorFactory =
      ProguardTranslatorFactory.create(
          projectFilesystem,
          Optional.of(proguardConfigFile),
          Optional.of(proguardMappingFile),
          false);

  Predicate<String> requiredInPrimaryZipPredicate =
      splitZipStep.createRequiredInPrimaryZipPredicate(
          translatorFactory, Suppliers.ofInstance(ImmutableList.of()));
  assertTrue(
      "Primary class should be in primary.", requiredInPrimaryZipPredicate.test("primary.class"));
  assertFalse(
      "Secondary class should be in secondary.",
      requiredInPrimaryZipPredicate.test("secondary.class"));
}

public void workspaceAndProjectsWithoutDependenciesTests()
    throws IOException, InterruptedException {
  WorkspaceAndProjectGenerator generator =
      new WorkspaceAndProjectGenerator(
          xcodeDescriptions,
          cells.getRootCell(),
          targetGraph,
          workspaceNode.getConstructorArg(),
          workspaceNode.getBuildTarget(),
          ProjectGeneratorOptions.builder()
              .setShouldIncludeTests(true)
              .setShouldGenerateProjectSchemes(true)
              .build(),
          FocusedTargetMatcher.noFocus(),
          false /* parallelizeBuild */,
          DEFAULT_PLATFORM,
          ImmutableSet.of(),
          "BUCK",
          getActionGraphBuilderForNodeFunction(targetGraph),
          getFakeBuckEventBus(),
          TestRuleKeyConfigurationFactory.create(),
          halideBuckConfig,
          cxxBuckConfig,
          appleConfig,
          swiftBuckConfig,
          Optional.empty());

  generator.generateWorkspaceAndDependentProjects(MoreExecutors.newDirectExecutorService());
  assertEquals(generator.getSchemeGenerators().size(), 1);

  // validate main scheme values
  Optional<XCScheme> mainScheme =
      generator.getSchemeGenerators().get("workspace").getOutputScheme();

  assertThat(mainScheme.isPresent(), is(true));

  XCScheme.BuildAction mainSchemeBuildAction = mainScheme.get().getBuildAction().get();
  List<BuildActionEntry> mainSchemeBuildActionEntries =
      mainSchemeBuildAction.getBuildActionEntries();
  assertThat(mainSchemeBuildActionEntries, hasSize(4));
  assertThat( // foo:bin
      mainSchemeBuildActionEntries,
      hasItem(withNameAndBuildingFor("bin", equalTo(BuildFor.MAIN_EXECUTABLE))));
  assertThat( // foo:bin-xctest
      mainSchemeBuildActionEntries,
      hasItem(withNameAndBuildingFor("bin-xctest", equalTo(BuildFor.TEST_ONLY))));
  assertThat( // foo:lib
      mainSchemeBuildActionEntries,
      hasItem(
          withNameAndBuildingFor(
              "lib", equalTo(XCScheme.BuildActionEntry.BuildFor.INDEXING_ONLY))));
  assertThat( // bar:libbar
      mainSchemeBuildActionEntries,
      hasItem(
          withNameAndBuildingFor(
              "libbar", equalTo(XCScheme.BuildActionEntry.BuildFor.INDEXING_ONLY))));

  XCScheme.TestAction mainSchemeTestAction = mainScheme.get().getTestAction().get();
  assertThat(mainSchemeTestAction.getTestables(), hasSize(1));
  assertThat( // foo:bin-xctest
      mainSchemeTestAction.getTestables(), hasItem(withName("bin-xctest")));
}

