code_method:
public void testAndroidBinaryNoDx() {
  ActionGraphBuilder graphBuilder = new TestActionGraphBuilder();
  SourcePathResolverAdapter pathResolver = graphBuilder.getSourcePathResolver();
  BuildContext buildContext = FakeBuildContext.withSourcePathResolver(pathResolver);

  // Two android_library deps, neither with an assets directory.
  BuildRule libraryOne =
      createAndroidLibraryRule(
          "//java/src/com/facebook/base:libraryOne",
          graphBuilder,
          null, /* resDirectory */
          null, /* assetDirectory */
          null /* nativeLibsDirectory */);
  BuildRule libraryOneRule = graphBuilder.getRule(libraryOne.getBuildTarget());
  BuildRule libraryTwo =
      createAndroidLibraryRule(
          "//java/src/com/facebook/base:libraryTwo",
          graphBuilder,
          null, /* resDirectory */
          null, /* assetDirectory */
          null /* nativeLibsDirectory */);
  BuildRule libraryTwoRule = graphBuilder.getRule(libraryTwo.getBuildTarget());

  // One android_binary rule that depends on the two android_library rules.
  BuildTarget binaryBuildTarget =
      BuildTargetFactory.newInstance("//java/src/com/facebook/base:apk");
  ImmutableSortedSet<BuildTarget> originalDepsTargets =
      ImmutableSortedSet.of(libraryOneRule.getBuildTarget(), libraryTwoRule.getBuildTarget());
  BuildRule keystoreRule = addKeystoreRule(graphBuilder);
  PathSourcePath proguardConfig = FakeSourcePath.of("proguard.cfg");
  AndroidBinary androidBinary =
      AndroidBinaryBuilder.createBuilder(binaryBuildTarget)
          .setOriginalDeps(originalDepsTargets)
          .setBuildTargetsToExcludeFromDex(ImmutableSet.of(libraryTwoRule.getBuildTarget()))
          .setManifest(FakeSourcePath.of("java/src/com/facebook/base/AndroidManifest.xml"))
          .setKeystore(keystoreRule.getBuildTarget())
          .setProguardConfig(proguardConfig)
          .build(graphBuilder);

  AndroidPackageableCollection packageableCollection =
      androidBinary.getAndroidPackageableCollection();
  ImmutableList.Builder<Step> commands = ImmutableList.builder();

  FakeBuildableContext buildableContext = new FakeBuildableContext();

  androidBinary
      .getEnhancementResult()
      .getNonPreDexedDex()
      .get()
      .addProguardCommands(
          packageableCollection.getClasspathEntriesToDex().stream()
              .map(pathResolver::getRelativePath)
              .collect(ImmutableSet.toImmutableSet()),
          pathResolver.getAllAbsolutePaths(packageableCollection.getProguardConfigs()),
          false,
          commands,
          buildableContext,
          buildContext);

  BuildTarget aaptPackageTarget =
      binaryBuildTarget.withFlavors(
          AndroidBinaryResourcesGraphEnhancer.AAPT_PACKAGE_FLAVOR,
          InternalFlavor.of(APKModuleGraph.ROOT_APKMODULE_NAME));
  Path aaptProguardDir =
      BuildTargetPaths.getGenPath(
          androidBinary.getProjectFilesystem(), aaptPackageTarget, "%s/proguard");

  Path proguardOutputDir =
      androidBinary.getEnhancementResult().getNonPreDexedDex().get().getProguardConfigDir();
  Path proguardInputsDir =
      androidBinary.getEnhancementResult().getNonPreDexedDex().get().getProguardInputsDir();
  ImmutableSet<Path> expectedRecordedArtifacts =
      ImmutableSet.of(
          proguardOutputDir.resolve("configuration.txt"),
          proguardOutputDir.resolve("mapping.txt"),
          proguardOutputDir.resolve("seeds.txt"),
          proguardOutputDir.resolve("usage.txt"));

  assertEquals(expectedRecordedArtifacts, buildableContext.getRecordedArtifacts());

  buildableContext = new FakeBuildableContext();

  ImmutableList.Builder<Step> expectedSteps = ImmutableList.builder();

  ProGuardObfuscateStep.create(
      TestAndroidPlatformTargetFactory.create(),
      JavaCompilationConstants.DEFAULT_JAVA_COMMAND_PREFIX,
      new FakeProjectFilesystem(),
      /* proguardJarOverride */ Optional.empty(),
      /* proguardMaxHeapSize */ "1024M",
      /* proguardAgentPath */ Optional.empty(),
      /* customProguardConfigs */ ImmutableSet.of(
          proguardConfig.getFilesystem().resolve(proguardConfig.getRelativePath()),
          proguardConfig.getFilesystem().resolve(aaptProguardDir.resolve("proguard.txt"))),
      ProGuardObfuscateStep.SdkProguardType.NONE,
      /* optimizationPasses */ ProGuardObfuscateStep.DEFAULT_OPTIMIZATION_PASSES,
      /* proguardJvmArgs */ Optional.empty(),
      ImmutableMap.of(
          BuildTargetPaths.getGenPath(
                  libraryOneRule.getProjectFilesystem(),
                  libraryOneRule.getBuildTarget(),
                  "lib__%s__output")
              .resolve(libraryOneRule.getBuildTarget().getShortName() + ".jar"),
          proguardInputsDir.resolve(
              BuildTargetPaths.getGenPath(
                      libraryOneRule.getProjectFilesystem(),
                      libraryOneRule.getBuildTarget(),
                      "lib__%s__output")
                  .resolve(
                      libraryOne.getBuildTarget().getShortNameAndFlavorPostfix()
                          + "-obfuscated.jar"))),
      ImmutableSet.of(
          androidBinary
              .getProjectFilesystem()
              .resolve(
                  BuildTargetPaths.getGenPath(
                          libraryTwoRule.getProjectFilesystem(),
                          libraryTwoRule.getBuildTarget(),
                          "lib__%s__output")
                      .resolve(
                          libraryTwoRule.getBuildTarget().getShortNameAndFlavorPostfix()
                              + ".jar"))),
      proguardOutputDir,
      buildableContext,
      buildContext,
      false,
      expectedSteps);

  assertEquals(expectedSteps.build(), commands.build());

  assertEquals(expectedRecordedArtifacts, buildableContext.getRecordedArtifacts());
}

public void createBuildRule() {

  ProjectFilesystem filesystem = new FakeProjectFilesystem();
  CxxPlatform cxxPlatform = CxxPlatformUtils.DEFAULT_PLATFORM;

  // Setup a genrule the generates a header we'll list.
  String genHeaderName = "test/foo.h";
  BuildTarget genHeaderTarget = BuildTargetFactory.newInstance("//:genHeader");
  GenruleBuilder genHeaderBuilder =
      GenruleBuilder.newGenruleBuilder(genHeaderTarget).setOut(genHeaderName);

  // Setup a genrule the generates a source we'll list.
  String genSourceName = "test/foo.cpp";
  BuildTarget genSourceTarget = BuildTargetFactory.newInstance("//:genSource");
  GenruleBuilder genSourceBuilder =
      GenruleBuilder.newGenruleBuilder(genSourceTarget).setOut(genSourceName);

  // Setup a C/C++ library that we'll depend on form the C/C++ binary description.
  BuildTarget sharedDepTarget =
      BuildTargetFactory.newInstance("//:sharedDep")
          .withAppendedFlavors(CxxDescriptionEnhancer.SHARED_FLAVOR);
  CxxLibraryBuilder sharedDepBuilder =
      new CxxLibraryBuilder(sharedDepTarget)
          .setExportedHeaders(
              SourceSortedSet.ofUnnamedSources(
                  ImmutableSortedSet.of(FakeSourcePath.of("blah.h"))))
          .setSrcs(
              ImmutableSortedSet.of(SourceWithFlags.of(FakeSourcePath.of("test_shared.cpp"))));
  BuildTarget sharedHeaderSymlinkTreeTarget =
      sharedDepTarget.withFlavors(
          CxxDescriptionEnhancer.EXPORTED_HEADER_SYMLINK_TREE_FLAVOR,
          HeaderMode.SYMLINK_TREE_ONLY.getFlavor());

  BuildTarget depTarget = BuildTargetFactory.newInstance("//:dep");
  CxxLibraryBuilder depBuilder =
      new CxxLibraryBuilder(depTarget)
          .setExportedHeaders(
              SourceSortedSet.ofUnnamedSources(
                  ImmutableSortedSet.of(FakeSourcePath.of("blah.h"))))
          .setSrcs(ImmutableSortedSet.of(SourceWithFlags.of(FakeSourcePath.of("test.cpp"))));
  BuildTarget headerSymlinkTreeTarget =
      depTarget.withAppendedFlavors(
          CxxDescriptionEnhancer.EXPORTED_HEADER_SYMLINK_TREE_FLAVOR,
          HeaderMode.SYMLINK_TREE_ONLY.getFlavor());

  // Setup the build params we'll pass to description when generating the build rules.
  BuildTarget target = BuildTargetFactory.newInstance("//:rule");
  CxxSourceRuleFactory cxxSourceRuleFactory =
      CxxSourceRuleFactoryHelper.of(filesystem.getRootPath().getPath(), target, cxxPlatform);

  String headerName = "test/bar.h";
  String privateHeaderName = "test/bar_private.h";
  CxxLibraryBuilder cxxLibraryBuilder =
      new CxxLibraryBuilder(target)
          .setExportedHeaders(
              ImmutableSortedSet.of(
                  FakeSourcePath.of(headerName),
                  DefaultBuildTargetSourcePath.of(genHeaderTarget)))
          .setHeaders(ImmutableSortedSet.of(FakeSourcePath.of(privateHeaderName)))
          .setSrcs(
              ImmutableSortedSet.of(
                  SourceWithFlags.of(FakeSourcePath.of("test/bar.cpp")),
                  SourceWithFlags.of(DefaultBuildTargetSourcePath.of(genSourceTarget))))
          .setFrameworks(
              ImmutableSortedSet.of(
                  FrameworkPath.ofSourcePath(FakeSourcePath.of("some/framework/path/s.dylib")),
                  FrameworkPath.ofSourcePath(
                      FakeSourcePath.of("another/framework/path/a.dylib"))))
          .setDeps(ImmutableSortedSet.of(depTarget, sharedDepTarget));

  // Build the target graph.
  TargetGraph targetGraph =
      TargetGraphFactory.newInstance(
          genHeaderBuilder.build(),
          genSourceBuilder.build(),
          depBuilder.build(),
          sharedDepBuilder.build(),
          cxxLibraryBuilder.build());

  // Build the rules.
  ActionGraphBuilder graphBuilder = new TestActionGraphBuilder(targetGraph);
  genHeaderBuilder.build(graphBuilder, filesystem, targetGraph);
  genSourceBuilder.build(graphBuilder, filesystem, targetGraph);
  depBuilder.build(graphBuilder, filesystem, targetGraph);
  sharedDepBuilder.build(graphBuilder, filesystem, targetGraph);
  CxxLibraryGroup rule =
      (CxxLibraryGroup) cxxLibraryBuilder.build(graphBuilder, filesystem, targetGraph);

  // Verify public preprocessor input.
  CxxPreprocessorInput publicInput = rule.getCxxPreprocessorInput(cxxPlatform, graphBuilder);
  assertThat(
      publicInput.getFrameworks(),
      containsInAnyOrder(
          FrameworkPath.ofSourcePath(
              FakeSourcePath.of(filesystem, "some/framework/path/s.dylib")),
          FrameworkPath.ofSourcePath(
              FakeSourcePath.of(filesystem, "another/framework/path/a.dylib"))));
  CxxSymlinkTreeHeaders publicHeaders = (CxxSymlinkTreeHeaders) publicInput.getIncludes().get(0);
  assertThat(publicHeaders.getIncludeType(), equalTo(CxxPreprocessables.IncludeType.LOCAL));
  assertThat(
      publicHeaders.getNameToPathMap(),
      equalTo(
          ImmutableMap.of(
              Paths.get(headerName),
              FakeSourcePath.of(headerName),
              Paths.get(genHeaderName),
              DefaultBuildTargetSourcePath.of(genHeaderTarget))));
  assertThat(
      publicHeaders.getHeaderMap(),
      equalTo(
          getHeaderMaps(filesystem, target, graphBuilder, cxxPlatform, HeaderVisibility.PUBLIC)));

  // Verify private preprocessor input.
  CxxPreprocessorInput privateInput =
      rule.getPrivateCxxPreprocessorInput(cxxPlatform, graphBuilder);
  assertThat(
      privateInput.getFrameworks(),
      containsInAnyOrder(
          FrameworkPath.ofSourcePath(
              FakeSourcePath.of(filesystem, "some/framework/path/s.dylib")),
          FrameworkPath.ofSourcePath(
              FakeSourcePath.of(filesystem, "another/framework/path/a.dylib"))));
  CxxSymlinkTreeHeaders privateHeaders =
      (CxxSymlinkTreeHeaders) privateInput.getIncludes().get(0);
  assertThat(privateHeaders.getIncludeType(), equalTo(CxxPreprocessables.IncludeType.LOCAL));
  assertThat(
      privateHeaders.getNameToPathMap(),
      equalTo(
          ImmutableMap.<Path, SourcePath>of(
              Paths.get(privateHeaderName), FakeSourcePath.of(privateHeaderName))));
  assertThat(
      privateHeaders.getHeaderMap(),
      equalTo(
          getHeaderMaps(
              filesystem, target, graphBuilder, cxxPlatform, HeaderVisibility.PRIVATE)));

  // Verify that the archive rule has the correct deps: the object files from our sources.
  rule.getNativeLinkableInput(
      cxxPlatform,
      Linker.LinkableDepType.STATIC,
      graphBuilder,
      UnconfiguredTargetConfiguration.INSTANCE);
  BuildRule archiveRule =
      graphBuilder.getRule(
          CxxDescriptionEnhancer.createStaticLibraryBuildTarget(
              target, cxxPlatform.getFlavor(), PicType.PDC));
  assertNotNull(archiveRule);
  assertEquals(
      ImmutableSet.of(
          cxxSourceRuleFactory.createCompileBuildTarget("test/bar.cpp"),
          cxxSourceRuleFactory.createCompileBuildTarget(genSourceName)),
      archiveRule.getBuildDeps().stream()
          .map(BuildRule::getBuildTarget)
          .collect(ImmutableSet.toImmutableSet()));

  // Verify that the compile rule for our user-provided source has correct deps setup
  // for the various header rules.
  BuildRule compileRule1 =
      graphBuilder.getRule(cxxSourceRuleFactory.createCompileBuildTarget("test/bar.cpp"));
  assertNotNull(compileRule1);
  assertThat(
      DependencyAggregationTestUtil.getDisaggregatedDeps(compileRule1)
          .map(BuildRule::getBuildTarget)
          .collect(ImmutableSet.toImmutableSet()),
      containsInAnyOrder(
          genHeaderTarget,
          headerSymlinkTreeTarget,
          sharedHeaderSymlinkTreeTarget,
          CxxDescriptionEnhancer.createHeaderSymlinkTreeTarget(
              target, HeaderVisibility.PRIVATE, cxxPlatform.getFlavor()),
          CxxDescriptionEnhancer.createHeaderSymlinkTreeTarget(
              target, HeaderVisibility.PUBLIC, HeaderMode.SYMLINK_TREE_ONLY.getFlavor())));

  // Verify that the compile rule for our genrule-generated source has correct deps setup
  // for the various header rules and the generating genrule.
  BuildRule compileRule2 =
      graphBuilder.getRule(cxxSourceRuleFactory.createCompileBuildTarget(genSourceName));
  assertNotNull(compileRule2);
  assertThat(
      DependencyAggregationTestUtil.getDisaggregatedDeps(compileRule2)
          .map(BuildRule::getBuildTarget)
          .collect(ImmutableSet.toImmutableSet()),
      containsInAnyOrder(
          genHeaderTarget,
          genSourceTarget,
          headerSymlinkTreeTarget,
          sharedHeaderSymlinkTreeTarget,
          CxxDescriptionEnhancer.createHeaderSymlinkTreeTarget(
              target, HeaderVisibility.PRIVATE, cxxPlatform.getFlavor()),
          CxxDescriptionEnhancer.createHeaderSymlinkTreeTarget(
              target, HeaderVisibility.PUBLIC, HeaderMode.SYMLINK_TREE_ONLY.getFlavor())));
}

public void createBuildRule() {
  ProjectFilesystem projectFilesystem = new FakeProjectFilesystem();
  CxxPlatform cxxPlatform = CxxPlatformUtils.DEFAULT_PLATFORM;

  // Setup a genrule the generates a header we'll list.
  String genHeaderName = "test/foo.h";
  BuildTarget genHeaderTarget = BuildTargetFactory.newInstance("//:genHeader");
  GenruleBuilder genHeaderBuilder =
      GenruleBuilder.newGenruleBuilder(genHeaderTarget).setOut(genHeaderName);

  // Setup a genrule the generates a source we'll list.
  String genSourceName = "test/foo.cpp";
  BuildTarget genSourceTarget = BuildTargetFactory.newInstance("//:genSource");
  GenruleBuilder genSourceBuilder =
      GenruleBuilder.newGenruleBuilder(genSourceTarget).setOut(genSourceName);

  // Setup a C/C++ library that we'll depend on form the C/C++ binary description.
  BuildTarget depTarget = BuildTargetFactory.newInstance("//:dep");
  CxxLibraryBuilder depBuilder =
      new CxxLibraryBuilder(depTarget)
          .setExportedHeaders(
              SourceSortedSet.ofUnnamedSources(
                  ImmutableSortedSet.of(FakeSourcePath.of("blah.h"))))
          .setSrcs(ImmutableSortedSet.of(SourceWithFlags.of(FakeSourcePath.of("test.cpp"))));
  BuildTarget archiveTarget =
      depTarget.withAppendedFlavors(
          CxxDescriptionEnhancer.STATIC_FLAVOR, cxxPlatform.getFlavor());
  BuildTarget headerSymlinkTreeTarget =
      depTarget.withAppendedFlavors(
          CxxDescriptionEnhancer.EXPORTED_HEADER_SYMLINK_TREE_FLAVOR,
          HeaderMode.SYMLINK_TREE_ONLY.getFlavor());

  // Setup the build params we'll pass to description when generating the build rules.
  BuildTarget target = BuildTargetFactory.newInstance("//:rule");
  CxxBinaryBuilder cxxBinaryBuilder =
      new CxxBinaryBuilder(target)
          .setSrcs(
              ImmutableSortedSet.of(
                  SourceWithFlags.of(FakeSourcePath.of("test/bar.cpp")),
                  SourceWithFlags.of(DefaultBuildTargetSourcePath.of(genSourceTarget))))
          .setHeaders(
              ImmutableSortedSet.of(
                  FakeSourcePath.of("test/bar.h"),
                  DefaultBuildTargetSourcePath.of(genHeaderTarget)))
          .setDeps(ImmutableSortedSet.of(depTarget));

  // Create the target graph.
  TargetGraph targetGraph =
      TargetGraphFactory.newInstance(
          genHeaderBuilder.build(),
          genSourceBuilder.build(),
          depBuilder.build(),
          cxxBinaryBuilder.build());

  // Create the build rules.
  ActionGraphBuilder graphBuilder = new TestActionGraphBuilder(targetGraph);
  genHeaderBuilder.build(graphBuilder, projectFilesystem, targetGraph);
  genSourceBuilder.build(graphBuilder, projectFilesystem, targetGraph);
  depBuilder.build(graphBuilder, projectFilesystem, targetGraph);
  CxxBinary binRule = cxxBinaryBuilder.build(graphBuilder, projectFilesystem, targetGraph);

  assertThat(binRule.getLinkRule(), Matchers.instanceOf(CxxLink.class));
  CxxLink rule = (CxxLink) binRule.getLinkRule();
  CxxSourceRuleFactory cxxSourceRuleFactory =
      CxxSourceRuleFactory.of(
          projectFilesystem,
          target,
          graphBuilder,
          graphBuilder.getSourcePathResolver(),
          CxxPlatformUtils.DEFAULT_CONFIG,
          cxxPlatform,
          ImmutableList.of(),
          ImmutableMultimap.of(),
          Optional.empty(),
          Optional.empty(),
          PicType.PDC);

  // Check that link rule has the expected deps: the object files for our sources and the
  // archive from the dependency.
  assertEquals(
      ImmutableSet.of(
          cxxSourceRuleFactory.createCompileBuildTarget("test/bar.cpp"),
          cxxSourceRuleFactory.createCompileBuildTarget(genSourceName),
          archiveTarget),
      rule.getBuildDeps().stream()
          .map(BuildRule::getBuildTarget)
          .collect(ImmutableSet.toImmutableSet()));

  // Verify that the compile rule for our user-provided source has correct deps setup
  // for the various header rules.
  BuildRule compileRule1 =
      graphBuilder.getRule(cxxSourceRuleFactory.createCompileBuildTarget("test/bar.cpp"));
  assertNotNull(compileRule1);
  assertThat(
      DependencyAggregationTestUtil.getDisaggregatedDeps(compileRule1)
          .map(BuildRule::getBuildTarget)
          .collect(ImmutableSet.toImmutableSet()),
      Matchers.containsInAnyOrder(
          genHeaderTarget,
          headerSymlinkTreeTarget,
          CxxDescriptionEnhancer.createHeaderSymlinkTreeTarget(
              target, HeaderVisibility.PRIVATE, cxxPlatform.getFlavor())));

  // Verify that the compile rule for our genrule-generated source has correct deps setup
  // for the various header rules and the generating genrule.
  BuildRule compileRule2 =
      graphBuilder.getRule(cxxSourceRuleFactory.createCompileBuildTarget(genSourceName));
  assertNotNull(compileRule2);
  assertThat(
      DependencyAggregationTestUtil.getDisaggregatedDeps(compileRule2)
          .map(BuildRule::getBuildTarget)
          .collect(ImmutableList.toImmutableList()),
      Matchers.containsInAnyOrder(
          genHeaderTarget,
          genSourceTarget,
          headerSymlinkTreeTarget,
          CxxDescriptionEnhancer.createHeaderSymlinkTreeTarget(
              target, HeaderVisibility.PRIVATE, cxxPlatform.getFlavor())));
}

public void testGetMatchingBuildTargets() {
  BuildTarget prebuiltJarTarget = BuildTargetFactory.newInstance("//empty:empty");
  TargetNode<?> prebuiltJarNode =
      PrebuiltJarBuilder.createBuilder(prebuiltJarTarget)
          .setBinaryJar(Paths.get("spoof"))
          .build();

  BuildTarget javaLibraryTarget = BuildTargetFactory.newInstance("//javasrc:java-library");
  TargetNode<?> javaLibraryNode =
      JavaLibraryBuilder.createBuilder(javaLibraryTarget)
          .addSrc(Paths.get("javasrc/JavaLibrary.java"))
          .addDep(prebuiltJarTarget)
          .build();

  BuildTarget javaTestTarget = BuildTargetFactory.newInstance("//javatest:test-java-library");
  TargetNode<?> javaTestNode =
      JavaTestBuilder.createBuilder(javaTestTarget)
          .addSrc(Paths.get("javatest/TestJavaLibrary.java"))
          .addDep(javaLibraryTarget)
          .build();

  ImmutableSet<TargetNode<?>> nodes =
      ImmutableSet.of(prebuiltJarNode, javaLibraryNode, javaTestNode);

  TargetGraph targetGraph = TargetGraphFactory.newInstance(nodes);

  ImmutableSet<RelPath> referencedFiles;

  // No target depends on the referenced file.
  referencedFiles = ImmutableSet.of(RelPath.get("excludesrc/CannotFind.java"));
  SortedMap<String, TargetNode<?>> matchingBuildRules =
      targetsCommand.getMatchingNodes(
          targetGraph,
          Optional.of(referencedFiles),
          Optional.empty(),
          Optional.empty(),
          false,
          "BUCK",
          filesystem);
  assertTrue(matchingBuildRules.isEmpty());

  // Only test-android-library target depends on the referenced file.
  referencedFiles = ImmutableSet.of(RelPath.get("javatest/TestJavaLibrary.java"));
  matchingBuildRules =
      targetsCommand.getMatchingNodes(
          targetGraph,
          Optional.of(referencedFiles),
          Optional.empty(),
          Optional.empty(),
          false,
          "BUCK",
          filesystem);
  assertEquals(ImmutableSet.of("//javatest:test-java-library"), matchingBuildRules.keySet());

  // The test-android-library target indirectly depends on the referenced file,
  // while test-java-library target directly depends on the referenced file.
  referencedFiles = ImmutableSet.of(RelPath.get("javasrc/JavaLibrary.java"));
  matchingBuildRules =
      targetsCommand.getMatchingNodes(
          targetGraph,
          Optional.of(referencedFiles),
          Optional.empty(),
          Optional.empty(),
          false,
          "BUCK",
          filesystem);
  assertEquals(
      ImmutableSet.of("//javatest:test-java-library", "//javasrc:java-library"),
      matchingBuildRules.keySet());

  // Verify that BUCK files show up as referenced files.
  referencedFiles = ImmutableSet.of(RelPath.get("javasrc/BUCK"));
  matchingBuildRules =
      targetsCommand.getMatchingNodes(
          targetGraph,
          Optional.of(referencedFiles),
          Optional.empty(),
          Optional.empty(),
          false,
          "BUCK",
          filesystem);
  assertEquals(
      ImmutableSet.of("//javatest:test-java-library", "//javasrc:java-library"),
      matchingBuildRules.keySet());

  // Output target only need to depend on one referenced file.
  referencedFiles =
      ImmutableSet.of(
          RelPath.get("javatest/TestJavaLibrary.java"), RelPath.get("othersrc/CannotFind.java"));
  matchingBuildRules =
      targetsCommand.getMatchingNodes(
          targetGraph,
          Optional.of(referencedFiles),
          Optional.empty(),
          Optional.empty(),
          false,
          "BUCK",
          filesystem);
  assertEquals(ImmutableSet.of("//javatest:test-java-library"), matchingBuildRules.keySet());

  // If no referenced file, means this filter is disabled, we can find all targets.
  matchingBuildRules =
      targetsCommand.getMatchingNodes(
          targetGraph,
          Optional.empty(),
          Optional.empty(),
          Optional.empty(),
          false,
          "BUCK",
          filesystem);
  assertEquals(
      ImmutableSet.of("//javatest:test-java-library", "//javasrc:java-library", "//empty:empty"),
      matchingBuildRules.keySet());

  // Specify java_test, java_library as type filters.
  matchingBuildRules =
      targetsCommand.getMatchingNodes(
          targetGraph,
          Optional.empty(),
          Optional.empty(),
          Optional.of(ImmutableSet.of(JavaTestDescription.class, JavaLibraryDescription.class)),
          false,
          "BUCK",
          filesystem);
  assertEquals(
      ImmutableSet.of("//javatest:test-java-library", "//javasrc:java-library"),
      matchingBuildRules.keySet());

  // Specify java_test, java_library, and a rule name as type filters.
  matchingBuildRules =
      targetsCommand.getMatchingNodes(
          targetGraph,
          Optional.empty(),
          Optional.of(ImmutableSet.of(BuildTargetFactory.newInstance("//javasrc:java-library"))),
          Optional.of(ImmutableSet.of(JavaTestDescription.class, JavaLibraryDescription.class)),
          false,
          "BUCK",
          filesystem);
  assertEquals(ImmutableSet.of("//javasrc:java-library"), matchingBuildRules.keySet());

  // Only filter by BuildTarget
  matchingBuildRules =
      targetsCommand.getMatchingNodes(
          targetGraph,
          Optional.empty(),
          Optional.of(ImmutableSet.of(BuildTargetFactory.newInstance("//javasrc:java-library"))),
          Optional.empty(),
          false,
          "BUCK",
          filesystem);
  assertEquals(ImmutableSet.of("//javasrc:java-library"), matchingBuildRules.keySet());

  // Filter by BuildTarget and Referenced Files
  matchingBuildRules =
      targetsCommand.getMatchingNodes(
          targetGraph,
          Optional.of(ImmutableSet.of(RelPath.get("javatest/TestJavaLibrary.java"))),
          Optional.of(ImmutableSet.of(BuildTargetFactory.newInstance("//javasrc:java-library"))),
          Optional.empty(),
          false,
          "BUCK",
          filesystem);
  assertEquals(ImmutableSet.<String>of(), matchingBuildRules.keySet());
}

