  Sequence seq = ql.runSimple(query, CalciteTests.SUPER_USER_AUTH_RESULT, AuthorizationResult.ALLOW_NO_RESTRICTION).getResults();
  List<Object> results = seq.toList();
  Assert.assertEquals(
      ImmutableList.of(ResultRow.of("def")),
      results
