private static ByteBuffer serialize(WritableSupplier<ColumnarMultiInts> writableSupplier)
    throws IOException

code_method:
public void setup() throws IOException
{
  Random rand = ThreadLocalRandom.current();
  List<int[]> rows = new ArrayList<>();
  final int bound = 1 << bytes;
  for (int i = 0; i < 0x100000; i++) {
    int count = rand.nextInt(valuesPerRowBound) + 1;
    int[] row = new int[rand.nextInt(count)];
    for (int j = 0; j < row.length; j++) {
      row[j] = rand.nextInt(bound);
    }
    rows.add(row);
  }

  final ByteBuffer bufferCompressed = serialize(
      CompressedVSizeColumnarMultiIntsSupplier.fromIterable(
          Iterables.transform(rows, (Function<int[], ColumnarInts>) input -> VSizeColumnarInts.fromArray(input, 20)),
          bound - 1,
          ByteOrder.nativeOrder(),
          CompressionStrategy.LZ4,
          Closer.create()
      )
  );
  this.compressed = CompressedVSizeColumnarMultiIntsSupplier.fromByteBuffer(
      bufferCompressed,
      ByteOrder.nativeOrder(),
      null
  ).get();

  final ByteBuffer bufferUncompressed = serialize(
      VSizeColumnarMultiInts.fromIterable(Iterables.transform(rows, input -> VSizeColumnarInts.fromArray(input, 20)))
  );
  this.uncompressed = VSizeColumnarMultiInts.readFromByteBuffer(bufferUncompressed);

  filter = new BitSet();
  for (int i = 0; i < filteredRowCount; i++) {
    int rowToAccess = rand.nextInt(rows.size());
    // Skip already selected rows if any
    while (filter.get(rowToAccess)) {
      rowToAccess = (rowToAccess + 1) % rows.size();
    }
    filter.set(rowToAccess);
  }
}

protected void buildRecipes() {
    var hasName = getHasName(Items.DIRT);
    var has = has(Items.DIRT);
    var items = this.registries.lookup(Registries.ITEM).get();

    // contains NBT match - should match a stone pickaxe that lost 3 durability, regardless of setting its name
    shaped()
        .pattern("XXX")
        .pattern("XXX")
        .define('X',
            partialNbt()
                .nbt(damaged())
                .items(Items.WOODEN_PICKAXE, Items.STONE_PICKAXE, Items.IRON_PICKAXE)
                .build()
        )
        .unlockedBy(hasName, has)
        .save(this.output, rk("partial_nbt_damage_only"));

    // contains NBT match - should match a named wood, stone, or iron pickaxe, regardless of damage
    shaped()
        .pattern("XXX")
        .define('X',
            partialNbt()
                .nbt(named())
                .items(Items.WOODEN_PICKAXE, Items.STONE_PICKAXE, Items.IRON_PICKAXE)
                .build()
        )
        .unlockedBy(hasName, has)
        .save(this.output, rk("partial_nbt_name_only"));

    // compound - should match named dirt or named oak logs
    shaped()
       .pattern("XXX")
       .pattern(" X ")
       .define('X', compound(
           strictNbt(named(Items.DIRT)),
           strictNbt(named(Items.OAK_LOG))
       ))
       .unlockedBy(hasName, has)
       .save(this.output, rk("compound_ingredient"));

    // strict NBT match - should match an unnamed pickaxe that lost 3 durability
    shaped()
        .pattern("XXX")
        .define('X', strictNbt(named(Items.DIAMOND_PICKAXE)))
        .unlockedBy(hasName, has)
        .save(this.output, rk("strict_nbt_ingredient"));

    // intersection - should match STONE only, [dirt, stone] + [stone, gravel]
    shaped()
        .pattern("XXX")
        .pattern("XXX")
        .pattern(" X ")
        .define('X', intersection(items, LEFT, RIGHT))
        .unlockedBy(hasName, has)
        .save(this.output, rk("intersection_ingredient"));

    // difference - should match DIRT only, [dirt, stone] - [stone, gravel]
    shaped()
       .pattern(" X ")
       .pattern("XXX")
       .pattern(" X ")
       .define('X', difference(items, LEFT, RIGHT))
       .unlockedBy(hasName, has)
       .save(this.output, rk("difference_ingredient"));
}

