public void testRemoveRulesOlderThanWithNonExistenceDatasourceAndOlderThanTimestampShouldDelete()
{
  List<Rule> rules = ImmutableList.of(
      new IntervalLoadRule(
          Intervals.of("2015-01-01/2015-02-01"),
