code_method:
public void testMakeStatsForDataSourceWithSkipped()
{
  // Only test and validate for one datasource for simplicity.
  // This dataSource has three intervals skipped (3 intervals, 1200 byte, 12 segments skipped by auto compaction)
  // Note that these segment used to be 10 bytes each in other tests, we are increasing it to 100 bytes each here
  // so that they will be skipped by the auto compaction.
  String dataSourceName = DATA_SOURCE_PREFIX + 1;
  List<DataSegment> segments = new ArrayList<>();
  for (int j : new int[]{0, 1, 2, 3, 7, 8}) {
    for (int k = 0; k < 4; k++) {
      DataSegment beforeNoon = createSegment(dataSourceName, j, true, k);
      DataSegment afterNoon = createSegment(dataSourceName, j, false, k);
      if (j == 3) {
        // Make two intervals on this day skipped (two skipped intervals back-to-back)
        beforeNoon = beforeNoon.withSize(100);
        afterNoon = afterNoon.withSize(100);
      }
      if (j == 1) {
        // Make one interval on this day skipped
        afterNoon = afterNoon.withSize(100);
      }
      segments.add(beforeNoon);
      segments.add(afterNoon);
    }
  }

  dataSources = DataSourcesSnapshot.fromUsedSegments(segments);

  final TestOverlordClient overlordClient = new TestOverlordClient(JSON_MAPPER);
  final CompactSegments compactSegments = new CompactSegments(statusTracker, overlordClient);

  // Before any compaction, we do not have any snapshot of compactions
  Map<String, AutoCompactionSnapshot> autoCompactionSnapshots = compactSegments.getAutoCompactionSnapshot();
  Assert.assertEquals(0, autoCompactionSnapshots.size());

  // 3 intervals, 1200 byte (each segment is 100 bytes), 12 segments will be skipped by auto compaction
  for (int compactionRunCount = 0; compactionRunCount < 8; compactionRunCount++) {
    // Do a cycle of auto compaction which creates one compaction task
    final CoordinatorRunStats stats = doCompactSegments(compactSegments);
    Assert.assertEquals(
        1,
        stats.get(Stats.Compaction.SUBMITTED_TASKS)
    );

    verifySnapshot(
        compactSegments,
        AutoCompactionSnapshot.AutoCompactionScheduleStatus.RUNNING,
        dataSourceName,
        // Minus 120 bytes accounting for the three skipped segments' original size
        TOTAL_BYTE_PER_DATASOURCE - 120 - 40 * (compactionRunCount + 1),
        40 * (compactionRunCount + 1),
        1240,
        TOTAL_INTERVAL_PER_DATASOURCE - 3 - (compactionRunCount + 1),
        (compactionRunCount + 1),
        4,
        TOTAL_SEGMENT_PER_DATASOURCE - 12 - 4 * (compactionRunCount + 1),
        4 + 2 * (compactionRunCount),
        16
    );
  }

  // Test that stats does not change (and is still correct) when auto compaction runs with everything is fully compacted
  final CoordinatorRunStats stats = doCompactSegments(compactSegments);
  Assert.assertEquals(
      0,
      stats.get(Stats.Compaction.SUBMITTED_TASKS)
  );
  verifySnapshot(
      compactSegments,
      AutoCompactionSnapshot.AutoCompactionScheduleStatus.RUNNING,
      dataSourceName,
      0,
      // Minus 120 bytes accounting for the three skipped segments' original size
      TOTAL_BYTE_PER_DATASOURCE - 120,
      1240,
      0,
      TOTAL_INTERVAL_PER_DATASOURCE - 3,
      4,
      0,
      16,
      16
  );
}

public void ingestingSketches() throws Exception
{
  Sequence<ResultRow> seq = helper.createIndexAndRunQueryOnSegment(
      new File(this.getClass().getClassLoader().getResource("quantiles/doubles_sketch_data.tsv").getFile()),
      String.join(
          "\n",
          "{",
          "  \"type\": \"string\",",
          "  \"parseSpec\": {",
          "    \"format\": \"tsv\",",
          "    \"timestampSpec\": {\"column\": \"timestamp\", \"format\": \"yyyyMMddHH\"},",
          "    \"dimensionsSpec\": {",
          "      \"dimensions\": [\"product\"],",
          "      \"dimensionExclusions\": [],",
          "      \"spatialDimensions\": []",
          "    },",
          "    \"columns\": [\"timestamp\", \"product\", \"sketch\"]",
          "  }",
          "}"
      ),
      String.join(
          "\n",
          "[",
          "  {\"type\": \"quantilesDoublesSketch\", \"name\": \"sketch\", \"fieldName\": \"sketch\", \"k\": 128},",
          "  {\"type\": \"quantilesDoublesSketch\", \"name\": \"non_existent_sketch\", \"fieldName\": \"non_existent_sketch\", \"k\": 128}",
          "]"
      ),
      0, // minTimestamp
      Granularities.NONE,
      10, // maxRowCount
      String.join(
          "\n",
          "{",
          "  \"queryType\": \"groupBy\",",
          "  \"dataSource\": \"test_datasource\",",
          "  \"granularity\": \"ALL\",",
          "  \"dimensions\": [],",
          "  \"aggregations\": [",
          "    {\"type\": \"quantilesDoublesSketch\", \"name\": \"sketch\", \"fieldName\": \"sketch\", \"k\": 128},",
          "    {\"type\": \"quantilesDoublesSketch\", \"name\": \"non_existent_sketch\", \"fieldName\": \"non_existent_sketch\", \"k\": 128}",
          "  ],",
          "  \"postAggregations\": [",
          "    {\"type\": \"quantilesDoublesSketchToQuantiles\", \"name\": \"quantiles\", \"fractions\": [0, 0.5, 1], \"field\": {\"type\": \"fieldAccess\", \"fieldName\": \"sketch\"}},",
          "    {\"type\": \"quantilesDoublesSketchToHistogram\", \"name\": \"histogram\", \"splitPoints\": [0.25, 0.5, 0.75], \"field\": {\"type\": \"fieldAccess\", \"fieldName\": \"sketch\"}}",
          "  ],",
          "  \"intervals\": [\"2016-01-01T00:00:00.000Z/2016-01-31T00:00:00.000Z\"]",
          "}"
      )
  );
  List<ResultRow> results = seq.toList();
  Assert.assertEquals(1, results.size());
  ResultRow row = results.get(0);

  Object nonExistentSketchObject = row.get(1);
  Assert.assertTrue(nonExistentSketchObject instanceof Long);
  long nonExistentSketchValue = (long) nonExistentSketchObject;
  Assert.assertEquals(0, nonExistentSketchValue);

  Object sketchObject = row.get(0);
  Assert.assertTrue(sketchObject instanceof Long);
  long sketchValue = (long) sketchObject;
  Assert.assertEquals(400, sketchValue);

  // post agg
  Object quantilesObject = row.get(2);
  Assert.assertTrue(quantilesObject instanceof double[]);
  double[] quantiles = (double[]) quantilesObject;
  Assert.assertEquals(0, quantiles[0], 0.05); // min value
  Assert.assertEquals(0.5, quantiles[1], 0.05); // median value
  Assert.assertEquals(1, quantiles[2], 0.05); // max value

  // post agg
  Object histogramObject = row.get(3);
  Assert.assertTrue(histogramObject instanceof double[]);
  double[] histogram = (double[]) histogramObject;
  for (final double bin : histogram) {
    // 400 items uniformly distributed into 4 bins
    Assert.assertEquals(100, bin, 100 * 0.2);
  }
}

